mapper.select:
select u.*, null as group_id, null as group_name from normal_user u
where u.admin_id = #{adminId}
  and not exists (
    select 1 from group_member gm
    inner join `group` g on g.id = gm.group_id
    where g.admin_id = #{adminId}
      and gm.user_id = u.id
  )
order by u.id desc

select u.*, #{groupId} as group_id, g.name as group_name from normal_user u
inner join group_member gm on gm.user_id = u.id
inner join `group` g on g.id = gm.group_id
where g.admin_id = #{adminId}
  and g.id = #{groupId}
order by u.id desc

select count(*) from normal_user
where id in

    #{id}

select * from normal_user
where id in

    #{id}
